{
  "mechanisms": [
    {
      "name": "mb_mf_mixture",
      "title": "MB/MF Mixture Weight",
      "description": "Combines model-based and model-free Q-values for Stage 1 choices using a mixing weight.",
      "params": [
        {
          "name": "w",
          "bounds": [
            0,
            1
          ]
        }
      ],
      "evidence": "q_net = w * q_stage1_mb + (1 - w) * q_stage1_mf",
      "expressible_in_slots": true
    },
    {
      "name": "choice_stickiness",
      "title": "Choice Stickiness",
      "description": "Adds a scalar bonus to the Stage 1 logit of the action that was chosen on the previous trial.",
      "params": [
        {
          "name": "stick",
          "bounds": [
            0,
            10
          ]
        }
      ],
      "evidence": "if trial > 0:\n            logits_1[action_1[trial-1]] += stick",
      "expressible_in_slots": true
    },
    {
      "name": "counterfactual_updating",
      "title": "Counterfactual Updating",
      "description": "Updates the unchosen Stage 2 action's value by assuming it would have yielded the opposite of the received reward, scaled by a specific learning rate multiplier.",
      "params": [
        {
          "name": "alpha_cf",
          "bounds": [
            0,
            1
          ]
        }
      ],
      "evidence": "unchosen_a2 = 1 - action_2[trial]\n\n        assumed_reward = 1 - reward[trial]\n        delta_cf = assumed_reward - q_stage2_mf[state_idx, unchosen_a2]\n        q_stage2_mf[state_idx, unchosen_a2] += learning_rate * alpha_cf * delta_cf",
      "expressible_in_slots": true
    },
    {
      "name": "eligibility_trace",
      "title": "Eligibility Trace",
      "description": "Updates the chosen Stage 1 model-free value using the Stage 2 reward prediction error, scaled by an eligibility trace parameter.",
      "params": [
        {
          "name": "lam",
          "bounds": [
            0,
            1
          ]
        }
      ],
      "evidence": "q_stage1_mf[action_1[trial]] += learning_rate * lam * delta_stage2",
      "expressible_in_slots": true
    },
    {
      "name": "value_decay",
      "title": "Value Decay",
      "description": "Decays the Q-values of unchosen Stage 1 actions and unvisited Stage 2 states towards the neutral value of 0.5.",
      "params": [
        {
          "name": "decay",
          "bounds": [
            0,
            1
          ]
        }
      ],
      "evidence": "for a in range(2):\n            if a != action_1[trial]:\n                q_stage1_mf[a] = (1 - decay) * q_stage1_mf[a] + decay * 0.5\n\n        for s in range(2):\n            if s != state_idx:\n                for a in range(2):\n                    q_stage2_mf[s, a] = (1 - decay) * q_stage2_mf[s, a] + decay * 0.5",
      "expressible_in_slots": true
    }
  ]
}
